const http=require('http'),PORT=+process.env.PORT||8787,HOST=process.env.HOST||'0.0.0.0',UA='Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36',C={'Access-Control-Allow-Origin':'*','Access-Control-Allow-Methods':'GET,HEAD,OPTIONS','Access-Control-Allow-Headers':'*','Access-Control-Expose-Headers':'Content-Length,Content-Range,Accept-Ranges,Content-Type'};
const sf=r=>(r.socket.encrypted?'https://':'http://')+(r.headers.host||'');
http.createServer(async(q,s)=>{
 if(q.method==='OPTIONS'){s.writeHead(204,C);return s.end()}
 const u=new URL(q.url,'http://x').searchParams.get('u');
 if(!u){s.writeHead(400,Object.assign({},C,{'Content-Type':'text/plain;charset=utf-8'}));return s.end('missing u')}
 let t;try{t=new URL(u)}catch{s.writeHead(400,C);return s.end('bad u')}
 if(!/^https?:$/.test(t.protocol)){s.writeHead(400,C);return s.end('only http/https')}
 const h={'User-Agent':UA,Accept:'*/*'};if(q.headers.range)h.Range=q.headers.range;
 try{
  const r=await fetch(u,{headers:h,redirect:'follow',signal:AbortSignal.timeout(20000)});
  const ct=r.headers.get('content-type')||'',pl=/mpegurl/i.test(ct)||/\.m3u8$/i.test(t.pathname),b=Object.assign({},C,{'Cache-Control':'no-cache'});
  const cr=r.headers.get('content-range'),ar=r.headers.get('accept-ranges');if(cr)b['Content-Range']=cr;if(ar)b['Accept-Ranges']=ar;
  if(pl){
   const x=await r.text(),ab=l=>{try{return new URL(l,u).toString()}catch{return l}},w=l=>sf(q).replace(/\/+$/,'')+'/?u='+encodeURIComponent(ab(l));
   const o=x.split(/\r?\n/).map(a=>{const l=a.trim();if(!l)return l;if(l[0]==='#')return l.replace(/URI="([^"]+)"/g,(m,p)=>'URI="'+w(p)+'"');return w(l)}).join('\n');
   s.writeHead(200,Object.assign({},b,{'Content-Type':'application/vnd.apple.mpegurl'}));return s.end(o)
  }
  b['Content-Type']=ct||'application/octet-stream';s.writeHead(r.status,b);s.end(Buffer.from(await r.arrayBuffer()))
 }catch(e){s.writeHead(502,Object.assign({},C,{'Content-Type':'text/plain;charset=utf-8'}));s.end('upstream error: '+(e&&e.message?e.message:e)+' | '+u)}
}).listen(PORT,HOST,()=>console.log('mini-proxy listening on http://'+HOST+':'+PORT+'/?u=<url>'));
